def beautifulSubstrings(s: str, k: int) -> int:
    p = 1
    count = 0

    while p <= k:
        i = 1
        while i * p % k != 0:
            i += 1
        p = i
        p *= 2

    sumdict = {0: {p - 1: 1}}
    cursum = 0
    vowels = {'a', 'e', 'i', 'o', 'u'}

    for i in range(len(s)):
        cursum = 0
        cate = i % p

        if s[i] in vowels:
            cursum += 1
        else:
            cursum -= 1

        cate = i % p

        if cursum in sumdict:
            if cate in sumdict[cursum]:
                count += sumdict[cursum][cate]
            else:
                sumdict[cursum][cate] = 1
        else:
            sumdict[cursum] = {cate: 1}

    return count
